// DOES THE CODE STILL DO WHAT THE MATRIX SAYS?
//
//   node --import ./scripts/ts-resolve-hook.mjs scripts/check-body-mode.mjs
//
// Ruth's matrix reply, 4 October 2026, item 7: "The final matrix is a
// machine-readable file that the checks read, so the code cannot drift from it."
//
// scripts/mode-matrix.json is that file. It is generated by build-mode-matrix.mjs
// from the real modules and committed, and this recomputes every row and compares.
// A difference means one of two things, and both need a person:
//
//   - the code changed and the matrix was not regenerated, so the document now
//     describes an app that no longer exists;
//   - the matrix was edited by hand, which is the one thing it must never be.
//
// THE POINT IS THE DIRECTION OF TRUTH. Every other document in this project has
// at some stage described what somebody believed the code did - the build log,
// the spec, nine status claims found false in one morning. This one cannot,
// because it is generated, and this check is what keeps it that way.
//
// It also holds the properties the matrix cannot state about itself: that the
// weight switches are mutually exclusive, that nothing chosen produces no figure,
// and that Pause is one rule rather than a second copy of every row.

import assert from 'node:assert';
import { readFileSync } from 'node:fs';

const root = 'file://' + process.cwd().replace(/\\/g, '/');
const MODE = await import(root + '/mobile/src/lib/body-mode.ts');
const INTENT = await import(root + '/mobile/src/lib/body-intent.ts');
const CAL = await import(root + '/mobile/src/lib/calorie-target.ts');
const PRO = await import(root + '/mobile/src/lib/protein.ts');

const matrix = JSON.parse(readFileSync('scripts/mode-matrix.json', 'utf8'));
const { body, switchOrder, rows } = matrix;

let pass = 0;
const failures = [];
function check(name, fn) {
  try {
    const note = fn();
    console.log(`  PASS  ${name}${note ? `   ${note}` : ''}`);
    pass += 1;
  } catch (e) {
    console.log(`  FAIL  ${name}\n          ${e.message}`);
    failures.push(name);
  }
}

const modeOf = (switches) =>
  Object.fromEntries(switchOrder.map((k, i) => [k, switches[i]]));

console.log('\n  THE CODE AND THE MATRIX AGREE\n');

check('the matrix covers every combination of the switches', () => {
  assert.strictEqual(rows.length, 2 ** switchOrder.length, `${rows.length} rows for ${switchOrder.length} switches`);
  return `${rows.length} combinations, ${rows.filter((r) => !r.blocked).length} reachable`;
});

check('every blocked row really is unreachable', () => {
  // The rule the UI dims for, asserted on the data rather than on the control.
  for (const r of rows.filter((x) => x.blocked)) {
    const mode = modeOf(r.switches);
    const on = MODE.WEIGHT_KEYS.filter((k) => mode[k]);
    assert.ok(on.length > 1, `${JSON.stringify(mode)} is marked blocked but only sets ${on.length} weight switch`);
    // And withToggle cannot produce it: turning one on turns the others off.
    for (const key of on) {
      const settled = MODE.withToggle(mode, key, true);
      assert.strictEqual(
        MODE.WEIGHT_KEYS.filter((k) => settled[k]).length,
        1,
        `withToggle left ${JSON.stringify(settled)} with more than one weight direction`
      );
    }
  }
  return `${rows.filter((r) => r.blocked).length} blocked, none reachable`;
});

check('every figure in the matrix is what the code computes now', () => {
  // THE WHOLE CHECK. Recompute each reachable row and compare.
  const drifted = [];
  for (const r of rows.filter((x) => !x.blocked)) {
    const mode = modeOf(r.switches);
    const focus = MODE.focusFromMode(mode);

    const name = MODE.modeLabel(mode);
    if (name !== r.name) drifted.push(`${r.name}: name is now "${name}"`);

    const line = MODE.modeExplanation(mode);
    if (line !== r.line) drifted.push(`${r.name}: the on-screen line changed`);

    const safety = MODE.modeSafetyLine(mode);
    if ((safety ?? null) !== (r.safety ?? null)) drifted.push(`${r.name}: the safety line changed`);

    if (!focus) {
      if (r.kcal !== null) drifted.push(`${r.name}: nothing chosen but the matrix shows ${r.kcal} kcal`);
      continue;
    }
    const cal = CAL.calculateCalorieTarget({
      tdeeKcal: body.tdeeKcal,
      weightKg: body.weightKg,
      bmrKcal: body.bmrKcal,
      fatFocus: focus.fat,
      muscleFocus: focus.muscle,
      // BUILD ALONE AND MAINTAIN + BUILD STORE THE SAME FOCUS PAIR and mean
      // different things, so the focus pair alone cannot recompute the row.
      // Leaving this out made the check report drift that was its own.
      weightDirectionStated: MODE.weightDirectionStated(mode),
    });
    if ((cal?.targetKcal ?? null) !== r.kcal) {
      drifted.push(`${r.name}: ${r.kcal} kcal in the matrix, ${cal?.targetKcal ?? 'null'} from the code`);
    }
    const pro = PRO.calculateProteinTarget({
      weightKg: body.weightKg,
      bodyFatPct: body.bodyFatPct,
      muscleFocus: focus.muscle,
    });
    const protein = pro?.kind === 'range' ? `${pro.low}–${pro.high} g` : null;
    if (protein !== r.protein) drifted.push(`${r.name}: protein ${r.protein} vs ${protein}`);
  }
  assert.ok(
    drifted.length === 0,
    drifted.join('\n          ') +
      '\n          Run `node --import ./scripts/ts-resolve-hook.mjs scripts/build-mode-matrix.mjs` ' +
      'if the code is right, or fix the code if the matrix is. Never edit the JSON by hand.'
  );
  return `${rows.filter((x) => !x.blocked).length} rows, every figure and every line`;
});

check('every state she can reach survives being saved and reloaded', () => {
  // SHE TICKED MAINTAIN AND BUILD, AND CAME BACK TO ONLY BUILD. Two stored
  // columns cannot tell "Maintain weight AND Build muscle" from "Build muscle,
  // nothing said about weight" - both are maintain/increase - so reading back had
  // to guess, and it guessed away one of her ticks.
  //
  // Build muscle now always carries a weight direction, which removes the
  // ambiguity instead of adding a column to carry it. This walks every state the
  // UI can actually produce, by building it the way the UI does.
  const reachable = [];
  for (const weight of [null, ...MODE.WEIGHT_KEYS]) {
    for (const build of [false, true]) {
      let mode = MODE.NO_MODE;
      if (weight) mode = MODE.withToggle(mode, weight, true);
      if (build) mode = MODE.withToggle(mode, 'buildMuscle', true);
      reachable.push(mode);
    }
  }
  const lost = [];
  for (const mode of reachable) {
    // THROUGH THE RECORD, which is what the app writes and reads. The two focus
    // columns are a derived VIEW and are lossy on purpose: Build alone and
    // Maintain + Build share a pair, which is exactly why body_mode exists.
    const written = MODE.modeWrite(mode);
    const back = MODE.modeFromRecord(written.body_mode);
    if (MODE.isEmpty(mode)) {
      if (written.body_mode !== null) lost.push('nothing chosen wrote a record');
      if (written.fat_focus_state !== null) lost.push('nothing chosen wrote a focus');
      continue;
    }
    for (const k of ['loseFat', 'maintainWeight', 'gainWeight', 'buildMuscle']) {
      if (Boolean(back?.[k]) !== Boolean(mode[k])) {
        lost.push(`${MODE.modeLabel(mode)}: ${k} was ${mode[k]}, came back ${back?.[k]}`);
      }
    }
  }
  assert.ok(lost.length === 0, lost.join('\n          '));
  return `${reachable.length} reachable states, none loses a tick`;
});

check('nothing chosen produces no figure at all', () => {
  // The distinction a silent default destroyed on 28 September, when three
  // people were shown a maintenance target nobody had chosen.
  const empty = rows.find((r) => !r.blocked && r.empty);
  assert.ok(empty, 'the matrix has no "nothing chosen" row');
  assert.strictEqual(empty.kcal, null, `nothing chosen shows ${empty.kcal} kcal`);
  assert.strictEqual(MODE.focusFromMode(MODE.NO_MODE), null, 'nothing chosen still writes a focus');
  // "NOTHING CHOSEN YET", NOT "NO GOAL CHOSEN" (Ruth, 5 October 2026). Her
  // distinction: "You choose your approach. Selodia provides the guide." A goal
  // is a thing you are measured against; an approach is what you are doing at the
  // moment, and not having picked one is not a failure to have a goal.
  //
  // The property under test is unchanged and is the one that matters: no choice,
  // no number, and nothing written to the focus columns.
  assert.ok(/Nothing chosen yet/.test(empty.line), `it reads "${empty.line}"`);
  assert.ok(!/goal/i.test(empty.line), `the empty line still says goal: "${empty.line}"`);
  return 'nothing chosen, no number'
;
});

check('the maintenance figure is never called a target', () => {
  // Her item 3. Maintenance is an observation about her body, and calling it a
  // target is how a number she did not choose starts reading as a test.
  const offenders = rows
    .filter((r) => !r.blocked)
    .filter((r) => /target/i.test(r.line ?? ''));
  assert.ok(offenders.length === 0, offenders.map((r) => `${r.name}: "${r.line}"`).join('\n          '));
  assert.ok(!/target/i.test(matrix.usesLine), `the uses line says target: "${matrix.usesLine}"`);
  assert.ok(
    !/a choice, not a default/i.test(rows.map((r) => r.line).join(' ')),
    'the removed "A choice, not a default" wording is back'
  );
  return 'describes, never sets';
});

check('Pause is one rule, not a second copy of every row', () => {
  assert.ok(matrix.paused, 'the matrix has no paused row');
  assert.strictEqual(
    matrix.paused.kcal,
    Math.round(body.tdeeKcal / 10) * 10,
    'paused is not simply what her body uses'
  );
  // The maintenance protein range, whatever the switches said.
  const plain = PRO.calculateProteinTarget({
    weightKg: body.weightKg,
    bodyFatPct: body.bodyFatPct,
    muscleFocus: 'maintain',
  });
  assert.strictEqual(matrix.paused.protein, `${plain.low}–${plain.high} g`, 'paused protein is not the maintenance range');
  assert.ok(/Resume/.test(matrix.paused.line), 'the paused line does not say how to come back');
  return `${matrix.paused.kcal} kcal · ${matrix.paused.protein}, for every combination`;
});

check('the gain-weight safety line appears on exactly the gain rows', () => {
  for (const r of rows.filter((x) => !x.blocked)) {
    const mode = modeOf(r.switches);
    const expected = mode.gainWeight;
    assert.strictEqual(
      Boolean(r.safety),
      expected,
      `${r.name} ${r.safety ? 'carries' : 'is missing'} the safety line`
    );
  }
  const gain = rows.find((r) => !r.blocked && modeOf(r.switches).gainWeight);
  // It states a fact and names nothing about her.
  assert.ok(/worth telling your doctor/.test(gain.safety), 'the wording changed');
  assert.ok(!/underweight|BMI/i.test(gain.safety), 'the app is labelling her body');
  return 'on every gain row, and nowhere else';
});

check('every rule carries its evidence and a review date', () => {
  // HER ITEM 3. A number nobody can state the reason for is a number nobody can
  // safely revise - and the monthly scan proposes changes against these entries,
  // so a rule with no basis is one the scan cannot reason about.
  assert.ok(Array.isArray(matrix.rules) && matrix.rules.length > 0, 'the matrix carries no rules');
  const bad = [];
  for (const r of matrix.rules) {
    if (!r.basis || r.basis.length < 40) bad.push(`${r.key}: no real basis`);
    if (!/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(r.lastReviewed ?? '')) bad.push(`${r.key}: no review date`);
    if (!r.value) bad.push(`${r.key}: no value`);
  }
  assert.ok(bad.length === 0, bad.join('\n          '));
  return `${matrix.rules.length} rules, each with its evidence and date`;
});

check('the stated rules are the ones the engine runs', () => {
  // THE WHOLE POINT OF WRITING THEM DOWN. A basis beside a constant that no
  // longer matches is worse than no basis at all: it reads as evidence for a
  // number the app is not using.
  const rule = (k) => matrix.rules.find((r) => r.key === k);
  assert.strictEqual(INTENT.gainSurplusKcal(200), 300, 'the stated ceiling of 300 does not bind');
  assert.strictEqual(INTENT.gainSurplusKcal(20), 100, 'the stated floor of 100 does not bind');
  assert.ok(
    /300/.test(rule('gain_bounds').value) && /100/.test(rule('gain_bounds').value),
    'the stated bounds do not name both numbers'
  );
  assert.strictEqual(INTENT.BUILD_SURPLUS_FRACTION, 0.05, 'the build surplus is not the stated 5%');
  assert.ok(/5%/.test(rule('build_surplus').value), 'the rule does not state 5%');
  assert.ok(/same/i.test(rule('energy_per_kg').basis), 'the shared-constant claim has gone');
  return 'bounds, fractions and constants all match the code';
});

console.log(`\n  ${pass} passed, ${failures.length} failed\n`);
if (failures.length > 0) process.exit(1);
